(function() {
    'use strict';

    class ModelOffAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'ModelOff: Financial Modeling Championship';
            this.version = '1.1.0';

            this.COMPANY = {
                baseRevenue: 265,
                baseEBITDAMargin: 14.3,
                netDebt: 125,
                sharesOutstanding: 50,
                taxRate: 0.21,
                currentStockPrice: 7.20,
                interestRate: 0.05,
                depreciationBase: 8
            };

            this.ROUNDS = [
                {
                    title: 'Round 1: Revenue and Margin Assumptions',
                    briefing: 'Set the 5-year revenue CAGR and target EBITDA margin for Meridian Logistics. Management guidance: 8-10% revenue CAGR, 14-15% EBITDA margin. Current revenue: €265M, EBITDA margin: 14.3%.',
                    input1: { label: 'Revenue CAGR (%)', hint: 'Guidance: 8-10%', min: 1, max: 20, step: 0.5, defaultVal: 9 },
                    input2: { label: 'EBITDA Margin (%)', hint: 'Guidance: 14-15%', min: 5, max: 25, step: 0.5, defaultVal: 14.5 },
                    optimal1: [8, 10],
                    optimal2: [14, 15.5]
                },
                {
                    title: 'Round 2: Cost Structure',
                    briefing: 'Set operating expense ratio and capital expenditure as percentages of revenue. Historical OpEx: 28-32% of revenue. CapEx guidance: 8-10% for automation and facility expansion.',
                    input1: { label: 'OpEx (% of Revenue)', hint: 'Historical: 28-32%', min: 15, max: 50, step: 0.5, defaultVal: 30 },
                    input2: { label: 'CapEx (% of Revenue)', hint: 'Guidance: 8-10%', min: 3, max: 20, step: 0.5, defaultVal: 9 },
                    optimal1: [28, 32],
                    optimal2: [8, 10]
                },
                {
                    title: 'Round 3: Working Capital',
                    briefing: 'Set days sales outstanding (DSO) and days payable outstanding (DPO). DSO guidance: 5-7 days. Industry DPO typically 25-35 days. Efficient working capital management drives free cash flow.',
                    input1: { label: 'DSO (Days)', hint: 'Guidance: 5-7 days', min: 1, max: 60, step: 1, defaultVal: 6 },
                    input2: { label: 'DPO (Days)', hint: 'Industry: 25-35 days', min: 10, max: 60, step: 1, defaultVal: 30 },
                    optimal1: [5, 7],
                    optimal2: [25, 35]
                },
                {
                    title: 'Round 4: DCF Valuation Parameters',
                    briefing: 'Set the weighted average cost of capital (WACC) and terminal growth rate for your DCF model. Benchmark WACC for 3PL: 7.5-9.5%. Terminal growth should approximate long-term GDP growth (2-3%).',
                    input1: { label: 'WACC (%)', hint: 'Benchmark: 7.5-9.5%', min: 4, max: 15, step: 0.1, defaultVal: 8.5 },
                    input2: { label: 'Terminal Growth (%)', hint: 'Long-term GDP: 2-3%', min: 0.5, max: 5, step: 0.1, defaultVal: 2.5 },
                    optimal1: [7.5, 9.5],
                    optimal2: [2, 3]
                },
                {
                    title: 'Round 5: Bull Case Scenario',
                    briefing: 'Build your upside scenario. Assume stronger market share gains, recovered pricing power, and operational leverage. What revenue CAGR and EBITDA margin would reflect an optimistic outcome?',
                    input1: { label: 'Bull Revenue CAGR (%)', hint: 'Upside: 11-14%', min: 5, max: 25, step: 0.5, defaultVal: 12 },
                    input2: { label: 'Bull EBITDA Margin (%)', hint: 'Upside: 15-17%', min: 10, max: 25, step: 0.5, defaultVal: 15.5 },
                    optimal1: [11, 14],
                    optimal2: [15, 17]
                },
                {
                    title: 'Round 6: Bear Case Scenario',
                    briefing: 'Build your downside scenario. Assume recession, customer churn, pricing pressure, and execution misses. What revenue CAGR and EBITDA margin reflect a conservative outcome?',
                    input1: { label: 'Bear Revenue CAGR (%)', hint: 'Downside: 3-6%', min: -5, max: 15, step: 0.5, defaultVal: 5 },
                    input2: { label: 'Bear EBITDA Margin (%)', hint: 'Downside: 11-13.5%', min: 5, max: 20, step: 0.5, defaultVal: 12.5 },
                    optimal1: [3, 6],
                    optimal2: [11, 13.5]
                },
                {
                    title: 'Round 7: M&A Evaluation',
                    briefing: 'Regional Logistics Inc (€80M revenue, €8M EBITDA) is available. Estimate annual cost synergies from the acquisition and set your maximum bid price. Asking price: €120M (15x EBITDA).',
                    input1: { label: 'Annual Cost Synergies (€M)', hint: 'Realistic: 4-8M', min: 0, max: 20, step: 0.5, defaultVal: 5 },
                    input2: { label: 'Max Bid Price (€M)', hint: 'Asking: €120M', min: 50, max: 200, step: 5, defaultVal: 110 },
                    optimal1: [4, 8],
                    optimal2: [90, 130]
                },
                {
                    title: 'Round 8: Investment Recommendation',
                    briefing: 'Present your final recommendation. Set a target share price based on your DCF analysis and assign a conviction score (1-10) reflecting confidence in your thesis. Current stock price: €7.20.',
                    input1: { label: 'Target Share Price (€)', hint: 'Current: €7.20', min: 1, max: 20, step: 0.1, defaultVal: 7.60 },
                    input2: { label: 'Conviction (1-10)', hint: 'How confident are you?', min: 1, max: 10, step: 1, defaultVal: 7 },
                    optimal1: [6.5, 9],
                    optimal2: [6, 9]
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    totalScore: 0,
                    roundScores: [],
                    enterpriseValue: 0,
                    sharePrice: 0,
                    lastRoundScore: 0,
                    scoreHistory: [],
                    evHistory: [],
                    revenueCagr: 9,
                    ebitdaMargin: 14.5,
                    opexPct: 30,
                    capexPct: 9,
                    dso: 6,
                    dpo: 30,
                    wacc: 8.5,
                    terminalGrowth: 2.5,
                    bullCagr: 12,
                    bullMargin: 15.5,
                    bearCagr: 5,
                    bearMargin: 12.5,
                    synergies: 5,
                    maxBid: 110,
                    targetPrice: 7.60,
                    conviction: 7
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    input1: 9,
                    input2: 14.5
                };
            }
            this._updateBriefing(state);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = round.title;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = round.briefing;

            var label1 = document.getElementById('input1Label');
            if (label1) label1.innerHTML = round.input1.label;

            var label2 = document.getElementById('input2Label');
            if (label2) label2.innerHTML = round.input2.label;

            var hint1 = document.getElementById('input1Hint');
            if (hint1) hint1.innerHTML = round.input1.hint;

            var hint2 = document.getElementById('input2Hint');
            if (hint2) hint2.innerHTML = round.input2.hint;

            var inp1 = document.getElementById('input1');
            if (inp1) {
                inp1.min = round.input1.min;
                inp1.max = round.input1.max;
                inp1.step = round.input1.step;
                inp1.value = round.input1.defaultVal;
            }

            var inp2 = document.getElementById('input2');
            if (inp2) {
                inp2.min = round.input2.min;
                inp2.max = round.input2.max;
                inp2.step = round.input2.step;
                inp2.value = round.input2.defaultVal;
            }
        }

        validateDecisions(decisions) {
            var inp1 = document.getElementById('input1');
            if (inp1) decisions.input1 = parseFloat(inp1.value);

            var inp2 = document.getElementById('input2');
            if (inp2) decisions.input2 = parseFloat(inp2.value);

            var idx = Math.min((window.mySimulation.state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            if (isNaN(decisions.input1) || decisions.input1 < round.input1.min || decisions.input1 > round.input1.max) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('input1_warning'), 'warning'
                );
                return false;
            }

            if (isNaN(decisions.input2) || decisions.input2 < round.input2.min || decisions.input2 > round.input2.max) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('input2_warning'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        _proximityScore(value, optMin, optMax) {
            if (value >= optMin && value <= optMax) return 100;
            var mid = (optMin + optMax) / 2;
            var halfRange = (optMax - optMin) / 2;
            var dist = 0;
            if (value < optMin) dist = optMin - value;
            else dist = value - optMax;
            var penalty = Math.min(100, (dist / Math.max(halfRange, 1)) * 60);
            return Math.max(0, Math.round(100 - penalty));
        }

        _computeEV(cagr, margin, wacc, tg) {
            var rev = this.COMPANY.baseRevenue;
            var totalPV = 0;
            var lastFCF = 0;
            for (var y = 1; y <= 5; y++) {
                rev = rev * (1 + cagr / 100);
                var ebitda = rev * margin / 100;
                var depreciation = this.COMPANY.depreciationBase + (rev * 0.09 * y * 0.1);
                var ebit = ebitda - depreciation;
                var interest = this.COMPANY.netDebt * this.COMPANY.interestRate;
                var preTax = ebit - interest;
                var tax = Math.max(0, preTax * this.COMPANY.taxRate);
                var netIncome = preTax - tax;
                var capex = rev * 0.09;
                var nwcChange = (rev * cagr / 100) * 0.015;
                var fcf = netIncome + depreciation - capex - nwcChange;
                totalPV += fcf / Math.pow(1 + wacc / 100, y);
                lastFCF = fcf;
            }
            // v1.1.0 guard: Gordon terminal value requires WACC > terminal growth.
            // Floor the spread at 0.5pp so WACC<=tg cannot produce Infinity/negative EV.
            var tvSpread = Math.max(wacc / 100 - tg / 100, 0.005);
            var tv = lastFCF * (1 + tg / 100) / tvSpread;
            var pvTV = tv / Math.pow(1 + wacc / 100, 5);
            return totalPV + pvTV;
        }

        calculateResults(state) {
            var d = state.decisions;
            var idx = state.currentPeriod - 1;
            var round = this.ROUNDS[Math.min(idx, this.ROUNDS.length - 1)];

            var score1 = this._proximityScore(d.input1, round.optimal1[0], round.optimal1[1]);
            var score2 = this._proximityScore(d.input2, round.optimal2[0], round.optimal2[1]);
            var roundScore = Math.round((score1 + score2) / 2);

            state.domainState.roundScores.push(roundScore);
            state.domainState.totalScore += roundScore;
            state.domainState.lastRoundScore = roundScore;
            state.domainState.scoreHistory.push(roundScore);

            // v1.1.0: persist a normalized 0-100 score and a performance object
            // in the shape the grading/reporting layer reads (score / performance.overallScore).
            var _played = state.domainState.roundScores.length;
            var _avg = _played ? (state.domainState.totalScore / _played) : 0;
            var _overall = Math.max(0, Math.min(100, Math.round(_avg)));
            var _rating = 'Analyst';
            if (_overall >= 75) _rating = 'Senior Analyst';
            if (_overall >= 85) _rating = 'Vice President';
            if (_overall >= 90) _rating = 'Managing Director';
            state.domainState.score = _overall;
            state.domainState.performance = {
                overallScore: _overall,
                rating: _rating,
                rawScore: state.domainState.totalScore
            };

            if (idx === 0) {
                state.domainState.revenueCagr = d.input1;
                state.domainState.ebitdaMargin = d.input2;
            } else if (idx === 1) {
                state.domainState.opexPct = d.input1;
                state.domainState.capexPct = d.input2;
            } else if (idx === 2) {
                state.domainState.dso = d.input1;
                state.domainState.dpo = d.input2;
            } else if (idx === 3) {
                state.domainState.wacc = d.input1;
                state.domainState.terminalGrowth = d.input2;
            } else if (idx === 4) {
                state.domainState.bullCagr = d.input1;
                state.domainState.bullMargin = d.input2;
            } else if (idx === 5) {
                state.domainState.bearCagr = d.input1;
                state.domainState.bearMargin = d.input2;
            } else if (idx === 6) {
                state.domainState.synergies = d.input1;
                state.domainState.maxBid = d.input2;
            } else if (idx === 7) {
                state.domainState.targetPrice = d.input1;
                state.domainState.conviction = d.input2;
            }

            var ev = this._computeEV(
                state.domainState.revenueCagr,
                state.domainState.ebitdaMargin,
                state.domainState.wacc,
                state.domainState.terminalGrowth
            );
            state.domainState.enterpriseValue = Math.round(ev);
            var equityVal = ev - this.COMPANY.netDebt;
            state.domainState.sharePrice = Math.round((equityVal / this.COMPANY.sharesOutstanding) * 100) / 100;
            state.domainState.evHistory.push(Math.round(ev));

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                input1: d.input1,
                input2: d.input2,
                roundScore: roundScore,
                totalScore: state.domainState.totalScore,
                enterpriseValue: state.domainState.enterpriseValue,
                sharePrice: state.domainState.sharePrice
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('totalScoreDisplay', 'domainState.totalScore',
                (v) => Math.round(v) + ' pts');
            uiManager.bind('evDisplay', 'domainState.enterpriseValue',
                (v) => '€' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('sharePriceDisplay', 'domainState.sharePrice',
                (v) => '€' + v.toFixed(2));
            uiManager.bind('roundScoreDisplay', 'domainState.lastRoundScore',
                (v) => v + '/100');
        }

        getChartConfig() {
            return {
                scoreChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Round Score',
                            data: [],
                            backgroundColor: 'rgba(249,168,37,0.7)',
                            borderColor: '#f9a825',
                            borderWidth: 2
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Round Scores' }
                        },
                        scales: {
                            y: { beginAtZero: true, max: 100 }
                        }
                    }
                },
                evChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Enterprise Value (€M)',
                            data: [],
                            borderColor: '#1a237e',
                            backgroundColor: 'rgba(26,35,126,0.1)',
                            borderWidth: 3,
                            fill: true,
                            tension: 0.3
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Enterprise Value Evolution' }
                        },
                        scales: {
                            y: { beginAtZero: false }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.scoreHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                scoreChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.scoreHistory }]
                },
                evChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.evHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};

            var scores = history.map(function(r) { return r.results ? r.results.roundScore || 0 : 0; });
            var totalScore = scores.reduce(function(s, v) { return s + v; }, 0);
            var avgScore = totalScore / scores.length;
            var maxPossible = history.length * 100;

            var lastEV = 0;
            var lastSP = 0;
            if (history.length > 0 && history[history.length - 1].results) {
                lastEV = history[history.length - 1].results.enterpriseValue || 0;
                lastSP = history[history.length - 1].results.sharePrice || 0;
            }

            var performance = 'Analyst';
            if (totalScore >= 600 && avgScore >= 75) performance = 'Senior Analyst';
            if (totalScore >= 680 && avgScore >= 85) performance = 'Vice President';
            if (totalScore >= 750 && avgScore >= 90) performance = 'Managing Director';

            var insights = [];
            if (avgScore >= 85) {
                insights.push('Excellent modeling discipline with well-calibrated assumptions across all rounds.');
            } else if (avgScore >= 70) {
                insights.push('Good modeling fundamentals. Review rounds with lower scores to refine your assumptions.');
            } else {
                insights.push('Focus on aligning assumptions with management guidance and industry benchmarks for stronger models.');
            }

            if (lastSP > 7.20) {
                insights.push('Your valuation suggests the stock is undervalued at the current price of €7.20.');
            } else {
                insights.push('Your valuation suggests the stock may be overvalued at the current price of €7.20.');
            }

            var overallScore = Math.max(0, Math.min(100, Math.round(avgScore)));
            return {
                totalScore: totalScore,
                avgScore: Math.round(avgScore),
                overallScore: overallScore,
                score: overallScore,
                maxPossible: maxPossible,
                enterpriseValue: lastEV,
                sharePrice: lastSP,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.roundScore >= 90) return window.mySimulation.t('hint_excellent');
            if (results.roundScore >= 70) return window.mySimulation.t('hint_good');
            if (results.roundScore >= 50) return window.mySimulation.t('hint_moderate');
            return window.mySimulation.t('hint_poor');
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.input1', label: 'Decision 1', i18nKey: 'col_input1', formatter: function(v) { return v.toFixed(1); } },
                { key: 'results.input2', label: 'Decision 2', i18nKey: 'col_input2', formatter: function(v) { return v.toFixed(1); } },
                { key: 'results.roundScore', label: 'Round Score', i18nKey: 'col_round_score', formatter: function(v) { return v + '/100'; } },
                { key: 'results.totalScore', label: 'Total Score', i18nKey: 'col_total_score' },
                { key: 'results.enterpriseValue', label: 'EV (€M)', i18nKey: 'col_ev', formatter: function(v) { return '€' + v.toLocaleString() + 'M'; } }
            ];
        }

        getPresets() { return null; }

        getTranslations() {
            return {
                en: {
                    title:              `ModelOff: Financial Modeling Championship`,
                    subtitle:           `Build a financial model for Meridian Logistics and evaluate an M&A opportunity`,
                    round_label:        `Round`,
                    period_of:          `of`,
                    round_title:        `Round 1: Revenue and Margin Assumptions`,
                    total_score_label:  `Total Score`,
                    ev_label:           `Enterprise Value`,
                    equity_label:       `Equity Value per Share`,
                    round_score_label:  `Round Score`,
                    decisions_heading:  `Your Modeling Decisions`,
                    input1_label:       `Revenue CAGR (%)`,
                    input2_label:       `EBITDA Margin (%)`,
                    input1_hint:        `Guidance: 8-10%`,
                    input2_hint:        `Guidance: 14-15%`,
